CREATE TABLE public.credit_transactions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, amount integer NOT NULL CHECK (amount <> 0), transaction_type text NOT NULL CHECK (transaction_type IN ('ad_reward', 'simulated_purchase', 'vip_purchase')), description text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamp with time zone NOT NULL DEFAULT now() );